package za.ac.smartpantry;
import android.app.*;import android.os.*;import android.widget.*;import java.time.*;
public class EditIngredientActivity extends Activity{
 private long id;private EditText name,quantity,expiry;private Spinner unit;private final String[] units={"pcs","piece","slice","g","kg","ml","l"};
 @Override public void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_edit);name=findViewById(R.id.nameField);quantity=findViewById(R.id.qtyField);expiry=findViewById(R.id.expiryField);unit=findViewById(R.id.unitField);ArrayAdapter<String> unitsAdapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,units);unit.setAdapter(unitsAdapter);id=getIntent().getLongExtra("id",-1);if(id>=0){Ingredient data=new PantryDatabase(this).getIngredient(id);if(data!=null){name.setText(data.name);quantity.setText(Double.toString(data.quantity));if(data.expiry!=null)expiry.setText(data.expiry);for(int k=0;k<units.length;k++)if(units[k].equals(data.unit))unit.setSelection(k);}}findViewById(R.id.saveButton).setOnClickListener(v->save());findViewById(R.id.cancelButton).setOnClickListener(v->finish());}
 private void save(){String n=name.getText().toString().trim(),q=quantity.getText().toString().trim(),e=expiry.getText().toString().trim();if(n.isEmpty()){name.setError("Ingredient name required");return;}if(!n.matches("[\\p{L}][\\p{L} \'-]*")){name.setError("Use ingredient words only");return;}double value;try{value=Double.parseDouble(q);}catch(Exception ex){quantity.setError("Enter a valid number");return;}if(!Double.isFinite(value)||value<=0){quantity.setError("Quantity must be positive");return;}if(!e.isEmpty()){try{LocalDate.parse(e);}catch(Exception ex){expiry.setError("Use YYYY-MM-DD");return;}}
 new PantryDatabase(this).saveIngredient(id,n,value,unit.getSelectedItem().toString(),e);Toast.makeText(this,"Ingredient saved",Toast.LENGTH_SHORT).show();finish();}
}